import { cookies } from "next/headers";
import { notFound } from "next/navigation";
import { resolveAuthContext } from "@/src/auth/service";
import { verifySessionToken as verifyLegacyToken } from "@/src/server/legacy-session";
import { AdminLiveHeader } from "@/components/admin/admin-live-header";
import { AdminSidebar } from "@/components/admin/AdminSidebar";

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const cookieStore = await cookies();
  const v2Token = cookieStore.get("xeurie_session_v2")?.value;
  const legacyToken = cookieStore.get("xeurie_session")?.value;

  let isAuthorized = false;

  // 1. Primary: Verify v2 session token & internal admin status
  if (v2Token) {
    try {
      const context = await resolveAuthContext(v2Token);
      if (context && context.isInternalAdmin) {
        isAuthorized = true;
      }
    } catch {}
  }

  // 2. Fallback: Legacy session token (Super Admin)
  if (!isAuthorized && legacyToken) {
    if (verifyLegacyToken(legacyToken)) {
      isAuthorized = true;
    }
  }

  // Invariant 3: Admin Invisibility Cloak — Returns HTTP 404 for unauthenticated or non-admin callers
  if (!isAuthorized) {
    notFound();
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-background text-foreground font-sans antialiased selection:bg-emerald-500/20 selection:text-emerald-400">
      {/* Glassmorphic Sidebar Navigation (4 Core Pillars) */}
      <AdminSidebar />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-transparent">
        <AdminLiveHeader />

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="w-full px-4 sm:px-6 py-4 sm:py-5">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}

