"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Percent, RefreshCw, Loader2, Trash2 } from "lucide-react";
import { useToast } from "@/app/components/Toast";

interface PromotionItem {
  id: number;
  code: string;
  title: string;
  discount_type: "PERCENTAGE" | "FIXED";
  discount_value: number;
  min_order_amount: number;
  usage_limit?: number | null;
  used_count: number;
  starts_at: string;
  expires_at?: string | null;
  is_active: boolean;
}

function formatDiscount(p: PromotionItem) {
  return p.discount_type === "PERCENTAGE" ? `${p.discount_value}%` : `₱${p.discount_value}`;
}

function formatDate(v?: string | null) {
  if (!v) return "—";
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString();
}

export function AdminPromotionsView() {
  const toast = useToast();
  const [promotions, setPromotions] = useState<PromotionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<number | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/promotions", { cache: "no-store", credentials: "include" });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false) {
        throw new Error(data.error || `HTTP ${res.status}`);
      }
      setPromotions(data.promotions || []);
    } catch (e: any) {
      setError(e?.message || "Failed to load promotions");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const handleDelete = async (p: PromotionItem) => {
    if (!window.confirm(`Delete promotion "${p.code}"? This cannot be undone.`)) return;
    setDeletingId(p.id);
    try {
      const res = await fetch(`/api/admin/promotions?id=${encodeURIComponent(String(p.id))}`, {
        method: "DELETE",
        credentials: "include",
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false || data.deleted === false) {
        throw new Error(data.error || "Delete failed");
      }
      setPromotions((prev) => prev.filter((x) => x.id !== p.id));
      toast.success?.(`Promotion ${p.code} deleted`);
    } catch (e: any) {
      toast.error?.(e?.message || "Delete failed");
    } finally {
      setDeletingId(null);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="flex items-center gap-2 text-lg font-semibold">
          <Percent className="w-5 h-5 text-emerald-500" /> Promotions
        </h1>
        <button
          type="button"
          onClick={load}
          disabled={loading}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-border text-xs hover:bg-muted/60 disabled:opacity-50"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} /> Refresh
        </button>
      </div>

      {error && (
        <div className="rounded-lg border border-rose-500/30 bg-rose-500/10 text-rose-500 text-xs p-3">{error}</div>
      )}

      {loading && promotions.length === 0 ? (
        <div className="flex items-center gap-2 text-xs text-muted-foreground py-8 justify-center">
          <Loader2 className="w-4 h-4 animate-spin" /> Loading promotions…
        </div>
      ) : promotions.length === 0 && !error ? (
        <div className="text-xs text-muted-foreground py-8 text-center">No promotions yet.</div>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-border">
          <table className="w-full text-xs">
            <thead className="bg-muted/50 text-left text-muted-foreground">
              <tr>
                <th className="px-3 py-2">Code</th>
                <th className="px-3 py-2">Title</th>
                <th className="px-3 py-2">Discount</th>
                <th className="px-3 py-2">Used</th>
                <th className="px-3 py-2">Expires</th>
                <th className="px-3 py-2">Status</th>
                <th className="px-3 py-2 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {promotions.map((p) => (
                <tr key={p.id} className="border-t border-border">
                  <td className="px-3 py-2 font-mono">{p.code}</td>
                  <td className="px-3 py-2">{p.title}</td>
                  <td className="px-3 py-2">{formatDiscount(p)}</td>
                  <td className="px-3 py-2">
                    {p.used_count}
                    {p.usage_limit ? ` / ${p.usage_limit}` : ""}
                  </td>
                  <td className="px-3 py-2">{formatDate(p.expires_at)}</td>
                  <td className="px-3 py-2">{p.is_active ? "Active" : "Inactive"}</td>
                  <td className="px-3 py-2 text-right">
                    <button
                      type="button"
                      onClick={() => handleDelete(p)}
                      disabled={deletingId === p.id}
                      aria-label={`Delete promotion ${p.code}`}
                      className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-rose-500 hover:bg-rose-500/10 disabled:opacity-50"
                    >
                      {deletingId === p.id ? (
                        <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      ) : (
                        <Trash2 className="w-3.5 h-3.5" />
                      )}
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

